-- SOURCE-FRESH: SCM_MGR 화면 SCP0104 객체·META (DB=ZIOUI1 SERVER_HOST=localhost) FETCHED=2026-11-17 10:16:45
/* 00_PRECHECK_CLOUD — 읽기 전용(변경 없음). 결과를 보고 진행
 * 패키지 SCP0104_CLOUD_DB_MOD_20261117_1016 · 생성 tools/CloudPkg/cloud_pkg.py 1.4.1 · 2026-11-17 10:16
 * 실행 계정 = SCM_MGR (전체 F5 · 반복 실행 안전)
 */
SET DEFINE OFF
SET SERVEROUTPUT ON SIZE UNLIMITED

/* 1) 화면 소유 객체 — 클라우드 현재 상태 (CLOUD_STATUS 빈칸 = 클라우드에 없음 → 이 패키지가 생성) */
SELECT E.N AS OBJECT_NAME, E.T AS OBJECT_TYPE, O.STATUS AS CLOUD_STATUS, TO_CHAR(O.LAST_DDL_TIME, 'YYYY-MM-DD HH24:MI') AS CLOUD_LAST_DDL
  FROM (SELECT 'FN_SCP0104_GET_CAPA_VERSION' N, 'FUNCTION' T FROM DUAL
    UNION ALL SELECT 'FN_SCP0104_GET_SPREAD_TITLE' N, 'FUNCTION' T FROM DUAL
    UNION ALL SELECT 'GT_SCP0104_ASGN_ALL' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_SCP0104_ASGN_CHG' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_SCP0104_ASGN_TOKEN' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_SCP0104_ASSIGN_RAW' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_SCP0104_CAPA_LOSS' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_SCP0104_DATE_COLS' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_SCP0104_DATE_VALS' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_SCP0104_DUMMY_LIVE' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_SCP0104_EQUIPMENT' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_SCP0104_EQUIP_TP_ASGN' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_SCP0104_LINE_MDL' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_SCP0104_SCP_MST_CAPA_LINE_SOP' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_SCP0104_SCP_MST_CAPA_LINE_SOP_TEMP' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_SCP0104_SCP_MST_CAPA_LOSS' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'PKG_SCP0104' N, 'PACKAGE' T FROM DUAL
    UNION ALL SELECT 'PKG_SCP0104' N, 'PACKAGE BODY' T FROM DUAL
    UNION ALL SELECT 'T_FN_SCP0104_CAPA_VERSION_ROW' N, 'TYPE' T FROM DUAL
    UNION ALL SELECT 'T_FN_SCP0104_CAPA_VERSION_TAB' N, 'TYPE' T FROM DUAL
    UNION ALL SELECT 'T_FN_SCP0104_SPREAD_TITLE_ROW' N, 'TYPE' T FROM DUAL
    UNION ALL SELECT 'T_FN_SCP0104_SPREAD_TITLE_TAB' N, 'TYPE' T FROM DUAL) E
  LEFT JOIN USER_OBJECTS O ON O.OBJECT_NAME = E.N AND O.OBJECT_TYPE = E.T
 ORDER BY 1, 2;

/* 2) 공용 참조 객체(이 패키지가 만들지 않음) — 0건이어야 정상. 행 = 클라우드에 없거나 INVALID → 먼저 이관 필요 */
SELECT E.O AS OWNER, E.N AS OBJECT_NAME, E.T AS OBJECT_TYPE, NVL(MAX(A.STATUS), '없음') AS CLOUD_STATUS
  FROM (SELECT 'SCM_MGR' O, 'FN_CHAR_TO_DATE' N, 'FUNCTION' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'FN_GET_DIVISION_NAME' N, 'FUNCTION' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'FN_SCM0002_GET_CAPA_ITEM_POPUP' N, 'FUNCTION' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'PR_SCM_SYS_LOG_BATCH_CALL_TRAN' N, 'PROCEDURE' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'SCM_ITEM_LANE_M_SN' N, 'SYNONYM' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'SCM_LINE_M_SN' N, 'SYNONYM' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'SCM_MMD_EQPT_PRDT_SPEED_SN' N, 'SYNONYM' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'SCM_MST_EQUIPMENT_SN' N, 'SYNONYM' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'SCM_MST_ITEM_CONV_CALC_SN' N, 'SYNONYM' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'SCM_MST_ITEM_SN' N, 'SYNONYM' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'SCM_MST_OPERATION_SN' N, 'SYNONYM' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'SEQ1_SCP_MST_CAPA_DUMMY_CODE' N, 'SEQUENCE' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'STRING_SPLIT' N, 'FUNCTION' T FROM DUAL) E
  LEFT JOIN ALL_OBJECTS A ON A.OWNER = E.O AND A.OBJECT_NAME = E.N AND A.OBJECT_TYPE IN (E.T, E.T || ' BODY')
 GROUP BY E.O, E.N, E.T
HAVING NVL(MAX(A.STATUS), '없음') <> 'VALID' OR MIN(A.STATUS) <> 'VALID'
 ORDER BY 1, 2;

/* 3) 참조 테이블·뷰 컬럼 누락 — 0건이어야 정상. 행 = 클라우드 표에 그 컬럼 없음 → PKG 컴파일 ORA-00904 원인.
 *    데이터·PK·배치 영향이 있어 자동 변경 안 함 — 결과를 그대로 전달(예: 2026-10-30 QA SCP_RPT_GLOBAL_PSI_MD_WW.PLAN_TYPE) */
