    UNION ALL SELECT 'SCM_MGR' O, 'SCP_MST_MDL_EQP_SPED' T, 'ATTRIBUTE7' C FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'SCP_MST_MDL_EQP_SPED' T, 'ATTRIBUTE8' C FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'SCP_MST_MDL_EQP_SPED' T, 'ATTRIBUTE9' C FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'SCP_MST_MDL_EQP_SPED' T, 'ATTRIBUTE10' C FROM DUAL) E
 WHERE NOT EXISTS (SELECT 1 FROM ALL_TABLES X WHERE X.OWNER = E.O AND X.TABLE_NAME = E.T)
   AND NOT EXISTS (SELECT 1 FROM ALL_VIEWS V WHERE V.OWNER = E.O AND V.VIEW_NAME = E.T)
   AND NOT EXISTS (SELECT 1 FROM ALL_SYNONYMS S WHERE S.OWNER = E.O AND S.SYNONYM_NAME = E.T)
 ORDER BY 1, 2;

/* 5) 상위 메뉴 존재 — 1건이어야 정상 */
SELECT MNU_ID, USE_YN FROM SCM_MGR.SCM_ADM_MNU_M WHERE MNU_ID = 'Capa Plan';

/* 6) META 현재 건수 (참고) */
SELECT 'SCM_ADM_MNU_M' AS TBL, '메뉴 행 (메뉴 트리·노출은 클라우드 운영값 존중 — 없을 때만)' AS AREA, COUNT(*) AS CLOUD_ROWS, 1 AS CORP_ROWS FROM SCM_MGR.SCM_ADM_MNU_M WHERE MNU_ID = 'SCP0104';
SELECT 'SCM_ADM_API_M' AS TBL, '화면 전용 API' AS AREA, COUNT(*) AS CLOUD_ROWS, 0 AS CORP_ROWS FROM SCM_MGR.SCM_ADM_API_M WHERE API_ID LIKE 'SCP0104' || '\_%' ESCAPE '\';
SELECT 'SCM_ADM_API_M' AS TBL, '공용 API(이 화면 버튼이 씀)' AS AREA, COUNT(*) AS CLOUD_ROWS, 14 AS CORP_ROWS FROM SCM_MGR.SCM_ADM_API_M WHERE API_ID IN (SELECT API_ID FROM SCM_MGR.SCM_ADM_MNU_BTN_MPG_M WHERE MNU_ID = 'SCP0104') AND API_ID NOT LIKE 'SCP0104' || '\_%' ESCAPE '\';
SELECT 'SCM_ADM_MNU_BTN_MPG_M' AS TBL, '버튼 → API 매핑' AS AREA, COUNT(*) AS CLOUD_ROWS, 31 AS CORP_ROWS FROM SCM_MGR.SCM_ADM_MNU_BTN_MPG_M WHERE MNU_ID = 'SCP0104';
SELECT 'SCM_ADM_PROC_M' AS TBL, '화면 PKG 프로시저 파라미터' AS AREA, COUNT(*) AS CLOUD_ROWS, 231 AS CORP_ROWS FROM SCM_MGR.SCM_ADM_PROC_M WHERE PROC_NM LIKE 'PKG\_' || 'SCP0104' || '.%' ESCAPE '\';
SELECT 'SCM_ADM_PROC_M' AS TBL, '공용 프로시저 파라미터' AS AREA, COUNT(*) AS CLOUD_ROWS, 0 AS CORP_ROWS FROM SCM_MGR.SCM_ADM_PROC_M WHERE PROC_NM IN (SELECT A.API_URL FROM SCM_MGR.SCM_ADM_API_M A JOIN SCM_MGR.SCM_ADM_MNU_BTN_MPG_M B ON B.API_ID = A.API_ID WHERE B.MNU_ID = 'SCP0104') AND PROC_NM NOT LIKE 'PKG\_' || 'SCP0104' || '.%' ESCAPE '\';
SELECT 'SCM_ADM_USER_GR_MNU_MPG_M' AS TBL, '그룹 메뉴 권한' AS AREA, COUNT(*) AS CLOUD_ROWS, 8 AS CORP_ROWS FROM SCM_MGR.SCM_ADM_USER_GR_MNU_MPG_M WHERE MNU_ID = 'SCP0104';
SELECT 'SCM_ADM_USER_GR_MNU_BTN_MPG_M' AS TBL, '그룹 버튼 권한' AS AREA, COUNT(*) AS CLOUD_ROWS, 228 AS CORP_ROWS FROM SCM_MGR.SCM_ADM_USER_GR_MNU_BTN_MPG_M WHERE MNU_ID = 'SCP0104';
SELECT 'SCM_MST_SHEET_COLUMNS' AS TBL, '시트 컬럼' AS AREA, COUNT(*) AS CLOUD_ROWS, 139 AS CORP_ROWS FROM SCM_MGR.SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID = 'SCP0104';
SELECT 'SCM_MST_SHEET_MEASURE' AS TBL, '시트 Measure' AS AREA, COUNT(*) AS CLOUD_ROWS, 0 AS CORP_ROWS FROM SCM_MGR.SCM_MST_SHEET_MEASURE WHERE PROGRAM_ID = 'SCP0104';
